#!/usr/bin/env node

/**
 * Generate `SupportedLocales.swift` from the `supported-locales.json` manifest
 * that the Vite build writes to `dist/`.
 *
 * The generated file is checked in, like the editor assets, so consumers
 * compile a constant and need no build plugin. Run by `make copy-ios-dist`.
 *
 * Usage: node bin/generate-supported-locales.js [manifest.json]
 */
import { existsSync, readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { error, info } from '../src/utils/logger.js';

const rootDir = join( dirname( fileURLToPath( import.meta.url ) ), '..' );
const manifestPath =
	process.argv[ 2 ] ?? join( rootDir, 'dist/supported-locales.json' );
const outputPath = join(
	rootDir,
	'ios/Sources/GutenbergKit/Sources/Model/SupportedLocales.swift'
);

if ( ! existsSync( manifestPath ) ) {
	error( `Missing ${ manifestPath }. Run \`make build\` to create it.` );
	process.exit( 1 );
}

const locales = JSON.parse( readFileSync( manifestPath, 'utf8' ) );
if (
	! Array.isArray( locales ) ||
	locales.length === 0 ||
	! locales.every( ( locale ) => typeof locale === 'string' )
) {
	error( `${ manifestPath } is not a non-empty JSON array of strings.` );
	process.exit( 1 );
}

const entries = [ ...new Set( locales ) ]
	.sort()
	.map( ( locale ) => `        "${ locale }",` )
	.join( '\n' );

const content = `// This file is auto-generated by bin/generate-supported-locales.js
// Do not edit manually - changes will be overwritten

/// The locale tags GutenbergKit ships translations for.
enum SupportedLocales {
    static let all: Set<String> = [
${ entries }
    ]
}
`;

writeFileSync( outputPath, content, 'utf8' );
info( `Generated ${ outputPath }` );
